-- ══════════════════════════════════════════════
--  quicktest.lua — the shell's Hyprland essentials, standalone
--
--  Generated by scripts/install-hypr-minimal.sh for someone who wants to keep
--  their own Hyprland config and just wire this shell into it, instead of
--  installing the full hypr/ bundle. Add ONE line near the top of your own
--  hyprland.lua (order doesn't matter — nothing here reads a global from your
--  config, or vice versa):
--
--      require("quicktest")
--
--  Needs Hyprland's Lua config (hyprland.lua), not hyprlang (hyprland.conf) —
--  hl.bind() / hl.layer_rule() / hl.window_rule() are the Lua config API.
--
--  @QUICKSHELL_DIR@ is rewritten to the real repo path by
--  scripts/install-hypr-minimal.sh. Re-run that script any time this repo
--  moves, or after a "git pull" adds a new bind here.
--
--  This is a DELIBERATE SUBSET of hypr/binds.lua + hypr/rules.lua — just the
--  lines the shell itself depends on to be reachable and to render correctly.
--  Everything else in the full bundle (app launchers, workspace binds, window
--  rules for games, monitors, animation curves, …) is this repo maintainer's
--  own taste and is left to your existing config on purpose.
-- ══════════════════════════════════════════════

-- Change this if your Hyprland modifier key isn't SUPER.
local mainMod = "SUPER"

-- ── Keybinds the shell needs a way in through ────────────────────────────────
-- Lock: the shell's lock screen, or hyprlock if the shell doesn't answer (scripts/lock.sh).
hl.bind(mainMod .. " + L",   hl.dsp.exec_cmd("@QUICKSHELL_DIR@/scripts/lock.sh"))
hl.bind(mainMod .. " + R",   hl.dsp.exec_cmd("qs ipc -c @QUICKSHELL_DIR@ call launcher toggle"))
hl.bind(mainMod .. " + TAB", hl.dsp.exec_cmd("qs ipc -c @QUICKSHELL_DIR@ call overview toggle"))
hl.bind(mainMod .. " + G",   hl.dsp.exec_cmd("qs ipc -c @QUICKSHELL_DIR@ call gamemode toggle"))
hl.bind(mainMod .. " + D",   hl.dsp.exec_cmd("qs ipc -c @QUICKSHELL_DIR@ call dock toggle"))
hl.bind("ALT + Q",           hl.dsp.exec_cmd("@QUICKSHELL_DIR@/scripts/reload-quickshell.sh"))

-- ── Layer rules the shell's surfaces need to render right ───────────────────
-- Blur behind the overview; explicitly none behind the bar (a layer_rule only
-- has an on/off switch — this is what keeps the bar crisp against the desktop
-- while the overview gets the same blur every other translucent surface does).
hl.layer_rule({ match = { namespace = "^quickshell-overview$" }, blur = true })
hl.layer_rule({ match = { namespace = "^quickshell-bar$" }, blur = false })

-- ── Qt apps in the shell's colours ──────────────────────────────────────────
-- The shell writes a qt6ct palette on every colour change (generate-qt6ct-colors);
-- a Qt6 app only reads it when this is in the environment Hyprland starts it with.
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

-- ── The shell's two real toplevels ───────────────────────────────────────────
-- Settings and the lyrics window are ordinary xdg-toplevels (not layer-shell
-- surfaces), so without these they'd tile like any other window instead of
-- floating centred.
hl.window_rule({
    match  = { class = [[^org\.quickshell$]], title = "^Settings$" },
    float  = true,
    center = true,
})
hl.window_rule({
    match  = { class = [[^org\.quickshell$]], title = "^Lyrics$" },
    float  = true,
    center = true,
})
